makeMtLab(document.getElementById("lab-l56"),{id:"l56",scenarios:[{"label": "Ví dụ: Dựng phần đầu MBAP", "note": "7 byte.", "steps": [{"t": "Mã giao dịch 1, giao thức 0", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">00 01 00 00<\/span><\/div>"}, {"t": "Độ dài 6, đơn vị 1", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">00 06 01<\/span><\/div>", "ask": {"q": "Vì sao độ dài là 6?", "o": ["1 byte đơn vị + 5 byte PDU", "Cố định", "Số thanh ghi"], "a": 0}}]}, {"label": "Ví dụ: PDU đọc 7 thanh ghi", "note": "Mã 03.", "steps": [{"t": "03 + địa chỉ 100", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">03 00 64<\/span><\/div>"}, {"t": "+ số lượng 7", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">03 00 64 00 07<\/span><\/div>"}]}, {"label": "Ví dụ: Giải mã phản hồi", "note": "Byte cao trước.", "steps": [{"t": "Số byte dữ liệu", "html": "<p class=\"mt-calc\">0x0E = 14 → 7 thanh ghi<\/p>"}, {"t": "Thanh ghi đầu", "html": "<p class=\"mt-calc\">00 06 → 6<\/p>", "ask": {"q": "00 82 là bao nhiêu?", "o": ["130", "33 280", "82"], "a": 0}}]}, {"label": "Lỗi: Dùng < thay cho >", "note": "Thứ tự byte của SLMP.", "steps": [{"t": "Đóng gói địa chỉ 100 bằng dấu nhỏ hơn", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">struct.pack('&lt;H', 100)  →  64 00<\/span><\/div>"}, {"t": "PLC hiểu là", "html": "<p class=\"mt-calc\">0x6400 = 25 600: ngoài dải hoặc đọc nhầm vùng<\/p>"}]}, {"label": "Bẫy: Không kiểm mã giao dịch", "note": "Hai yêu cầu chồng nhau.", "steps": [{"t": "Gửi yêu cầu 1 và 2 liên tiếp", "html": "<p class=\"mt-calc\">Phản hồi 2 có thể tới trước<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">So mã giao dịch, hoặc gửi tuần tự từng yêu cầu<\/p>"}]}]});
